/**
 * Merge driver for measurement results (results/*.json that record a timing or a measured
 * quantity). The gate-regenerated pass/fail files keep the current side (the `a0-results` driver,
 * regenerated by the gate); a measurement file must never lose a load-gated run to an ungated one,
 * so this driver chooses by what the files say about how they were recorded:
 *
 *   1. a side that only one branch changed is taken as is (git does not even call the driver then);
 *   2. both sides changed: prefer the run with a `loadGate` (the benchmark waited for a quiet
 *      machine) over one without;
 *   3. then the lower recorded load (loadGate.highestLoadAtSampleStart, else the highest number in
 *      `load` / `loadAverage`; a run with no load record counts as the worst);
 *   4. then the newer `generatedAt`;
 *   5. a log (`entries` array, results/dev-loop.json) is the union of both sides in time order;
 *   6. anything else is a conflict: the driver exits 1 and leaves the file for a person.
 *
 * Usage as a git merge driver (the clone configuration is `a0-dev setup`):
 *   node dist/tools/dev/merge-results.js %O %A %B %P     (writes the result into %A)
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

export type Side = 'ours' | 'theirs';

interface Recorded {
  readonly gated: boolean;
  /** The highest load the run recorded, or Infinity when it recorded none. */
  readonly load: number;
  readonly at: string;
}

function numbersIn(value: unknown, out: number[] = []): number[] {
  if (typeof value === 'number' && Number.isFinite(value)) out.push(value);
  else if (Array.isArray(value)) for (const v of value) numbersIn(v, out);
  else if (typeof value === 'object' && value !== null)
    for (const v of Object.values(value)) numbersIn(v, out);
  return out;
}

/** What a results object says about how it was recorded. */
export function recordedAs(doc: unknown): Recorded {
  const o = (typeof doc === 'object' && doc !== null ? doc : {}) as Record<string, unknown>;
  const gate = o.loadGate;
  const gated = typeof gate === 'object' && gate !== null;
  let load = Number.POSITIVE_INFINITY;
  if (gated) {
    const high = (gate as Record<string, unknown>).highestLoadAtSampleStart;
    if (typeof high === 'number') load = high;
    else {
      const max = (gate as Record<string, unknown>).maxLoad;
      if (typeof max === 'number') load = max;
    }
  }
  if (!Number.isFinite(load)) {
    const nums = [...numbersIn(o.load), ...numbersIn(o.loadAverage), ...numbersIn(o.loadAverages)];
    if (nums.length > 0) load = Math.max(...nums);
  }
  return { gated, load, at: typeof o.generatedAt === 'string' ? o.generatedAt : '' };
}

export interface Choice {
  readonly side: Side | 'union' | 'conflict';
  readonly why: string;
}

/** Which side a merge keeps, from the two parsed documents (and the base, when there is one). */
export function chooseMeasurement(base: unknown, ours: unknown, theirs: unknown): Choice {
  const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b);
  if (same(ours, theirs)) return { side: 'ours', why: 'both sides are the same' };
  if (base !== undefined && same(ours, base)) return { side: 'theirs', why: 'only theirs changed' };
  if (base !== undefined && same(theirs, base)) return { side: 'ours', why: 'only ours changed' };
  const isLog = (d: unknown): boolean =>
    typeof d === 'object' && d !== null && Array.isArray((d as { entries?: unknown }).entries);
  if (isLog(ours) && isLog(theirs)) return { side: 'union', why: 'a log: both sides kept' };
  const a = recordedAs(ours);
  const b = recordedAs(theirs);
  if (a.gated !== b.gated)
    return { side: a.gated ? 'ours' : 'theirs', why: 'only one run was load-gated' };
  if (a.load !== b.load)
    return { side: a.load < b.load ? 'ours' : 'theirs', why: 'lower recorded load' };
  if (a.at !== b.at && a.at !== '' && b.at !== '')
    return { side: a.at > b.at ? 'ours' : 'theirs', why: 'newer run' };
  return { side: 'conflict', why: 'nothing says which run to keep' };
}

/** The union of two logs (`entries`), de-duplicated and in time order. */
export function unionLogs(ours: unknown, theirs: unknown): unknown {
  const o = ours as { entries: unknown[] } & Record<string, unknown>;
  const t = theirs as { entries: unknown[] };
  const seen = new Set<string>();
  const entries: unknown[] = [];
  for (const e of [...o.entries, ...t.entries]) {
    const key = JSON.stringify(e);
    if (seen.has(key)) continue;
    seen.add(key);
    entries.push(e);
  }
  entries.sort((x, y) =>
    String((x as { at?: string }).at ?? '').localeCompare(String((y as { at?: string }).at ?? '')),
  );
  return { ...o, entries };
}

/** Merge three file contents; undefined means a conflict (the caller exits 1). */
export function mergeMeasurementText(
  baseText: string | undefined,
  oursText: string,
  theirsText: string,
): string | undefined {
  let ours: unknown;
  let theirs: unknown;
  let base: unknown;
  try {
    ours = JSON.parse(oursText);
    theirs = JSON.parse(theirsText);
    base = baseText === undefined || baseText.trim() === '' ? undefined : JSON.parse(baseText);
  } catch {
    return undefined;
  }
  const c = chooseMeasurement(base, ours, theirs);
  if (c.side === 'conflict') return undefined;
  if (c.side === 'union') return `${JSON.stringify(unionLogs(ours, theirs), null, 2)}\n`;
  return c.side === 'ours' ? oursText : theirsText;
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const [basePath, oursPath, theirsPath, name] = process.argv.slice(2);
  if (oursPath === undefined || theirsPath === undefined) {
    process.stderr.write('usage: merge-results.js %O %A %B %P\n');
    process.exit(2);
  }
  const read = (p: string | undefined): string | undefined => {
    if (p === undefined) return undefined;
    try {
      return readFileSync(p, 'utf8');
    } catch {
      return undefined;
    }
  };
  const merged = mergeMeasurementText(read(basePath), read(oursPath) ?? '', read(theirsPath) ?? '');
  if (merged === undefined) {
    process.stderr.write(
      `merge-results: ${name ?? 'results'}: no rule says which side to keep; resolve it by hand\n`,
    );
    process.exit(1);
  }
  writeFileSync(oursPath, merged, 'utf8');
}
